import{_ as i,l as n,o as a,c,v as t,p as d,x as o,d as s,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"封装与不变量","description":"","frontmatter":{"title":"封装与不变量","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/encapsulation-invariant.md","filePath":"cs/encapsulation-invariant.md","lastUpdated":1789023840000}'),E={name:"cs/encapsulation-invariant.md"};function h(u,e,A,B,_,m){const r=n("Mermaid");return a(),c("div",null,[e[1]||(e[1]=t('<h1 id="封装与不变量" tabindex="-1">封装与不变量 <a class="header-anchor" href="#封装与不变量" aria-label="Permalink to &quot;封装与不变量&quot;">​</a></h1><div class="epigraph"><p>不变量是对象在公开操作之间必须保持的性质；封装把能打破它的存储藏起来，只留维持它的函数。</p><footer>—— 据 Kernighan &amp; Ritchie, The C Programming Language, 2nd ed.；ISO/IEC 9899 整理</footer></div><p>上一课<a href="/cs/vcs-changeset">版本控制与变更</a>把接口改动收成可回放的差。本课不重讲提交，也不从 Java 可见性修饰符另起。缺口是：头文件已经能分享结构体布局，<strong>一旦调用方直接改字段，函数边界上的契约就会被绕开</strong>。封装是为不变量服务的，不是为了「看起来像对象」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>结构体课给出了公开字段与偏移。若任何翻译单元都能写 <code>s-&gt;count++</code>，则「<code>count</code> 与链表长度一致」无法只靠一组函数来维持。缺口因此不是再加几个函数，而是<strong>谁被允许碰表示</strong>。C 用编译单元加不完整类型：调用方只有 <code>Foo *</code>，完整 <code>struct Foo</code> 放在实现文件里。公开头文件只声明创建、查询、修改、销毁。</p><p>不变量在构造（或初始化函数）后为真，每个公开函数假设进入时为真、返回时仍为真。失败路径也必须维持它或把对象标为不可用并释放。测试可以断言公开可观察的性质；内部断言辅助实现，但不替代封装——内部断言挡不住另一个 <code>.c</code> 直接写字段，若布局被公开的话。</p><h3 id="封装不是「加一层-getter」" tabindex="-1">封装不是「加一层 getter」 <a class="header-anchor" href="#封装不是「加一层-getter」" aria-label="Permalink to &quot;封装不是「加一层 getter」&quot;">​</a></h3><p>若 getter/setter 只是把字段原样暴露，不变量仍可以在两次调用之间被组合破坏（先改长度再忘了改指针）。封装要限制<strong>允许的状态转移</strong>，不是给每个字段改个名字。把封装理解成访问器生成，会回到公开布局，只是多了函数调用税。</p><p><span class="marginnote">K&amp;R 用静态函数和文件作用域静态变量隐藏实现。ISO C 的不完整类型让指针在头文件里可用、布局不可用。本课不把 C++ <code>private</code> 当默认语法，机制相同：表示不可从边界外写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定表示（计数、头指针、容量）。写出不变量：例如「<code>len</code> 等于从 <code>head</code> 走访的节点数，且所有节点由本对象拥有」。公开函数只通过内部辅助改这些字段。创建函数建立不变量；销毁函数释放所有权并结束寿命。调用方不得保存内部节点指针越过可能使其无效的操作——那条要写进契约，与悬挂课衔接。</p>',11)),(a(),d(p,null,{default:o(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REP%5B%22%E8%A1%A8%E7%A4%BA%E8%97%8F%E5%9C%A8%E5%AE%9E%E7%8E%B0%E6%96%87%E4%BB%B6%22%5D%20--%3E%20INV%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%0A%20%20INV%20--%3E%20API%5B%22%E5%85%AC%E5%BC%80%E5%87%BD%E6%95%B0%E7%BB%B4%E6%8C%81%E5%AE%83%22%5D%0A%20%20OPEN%5B%22%E5%85%AC%E5%BC%80%E5%AD%97%E6%AE%B5%22%5D%20--%3E%20BREAK%5B%22%E8%B0%83%E7%94%A8%E6%96%B9%E5%8F%AF%E6%89%93%E7%A0%B4%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%0A%20%20BREAK%20--%3E%20FAIL%5B%22%E5%A5%91%E7%BA%A6%E4%B8%8D%E5%86%8D%E5%8F%AF%E6%B5%8B%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>文件作用域 <code>static</code> 让辅助函数与表不进入链接器的全局符号，减少上一课那种「不该出现在公开差里」的符号。这是封装在链接层面的对应。</p><p>创建与销毁必须成对出现在公开面上：只暴露修改、不暴露创建，调用方就只能去猜布局并自己 <code>malloc</code>，封装立刻失败。不变量检查可以放在每个公开函数入口的断言里，发行配置关掉后仍靠类型不完整来挡外部写入。多文件模块若把完整 <code>struct</code> 放进「内部头」再被外部偷偷包含，封装是社会约定而不是编译器强制——审查与包含路径要挡住这条。后课虚表把操作入口收成一张表，表示仍然只在实现文件里完整。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不变量把推理从「任意比特组合」缩小到「合法状态」。调试时先查不变量是否破，再查算法。并发课会证明：没有封装，锁也不知道该保护哪一块。本课仍是单线程：共享可变是后课，但已经能看出，可变表示必须有唯一的修改入口，否则入口太多等于没有不变量。</p><p>不完整类型把偏移从调用方的编译单元里拿走：他们不能写 <code>p-&gt;len</code>，因为 <code>struct</code> 在该单元里没有成员。这比「请不要碰」的注释硬。测试若为了图方便把内部头文件包含进用例，等于把不变量的检查改成对表示的快照，重构一次就全红——那是在测试实现，不是测契约。文件作用域静态表也是封装：链接器不导出，别人即使用 <code>extern</code> 声明也链不上。后课虚表在封装之上加间接，表示仍然不完整。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲继承，不把虚函数请来。下一课<a href="/cs/vtable-preview">动态分派与虚表</a>在封装之上加「同一契约、多种表示」。后课默认：合法状态由不变量刻画；表示默认不完整；公开函数是唯一切换状态的入口。调用方保存内部节点指针越过可能使其无效的操作，仍是悬挂，封装不能代替寿命契约。</p><p>不变量要用公开可观察的量来陈述，才能被测试执行。内部节点形状可以变，只要长度、顺序、失败语义不变。把内部指针比对外公布，封装就只剩注释。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不变量是公开操作之间保持的性质；封装禁止从外部打破表示。</li><li>不完整类型加实现文件是 C 的主要手段。</li><li>访问器若原样暴露字段，就没有封装。</li><li>测试应对公开可观察量，不要冻结内部布局。</li><li>下一课让同一接口背后换实现，而不改调用方。</li><li>出处：K&amp;R 静态与多文件隐藏；ISO C 不完整类型。</li></ul>',10))])}const C=i(E,[["render",h]]);export{f as __pageData,C as default};
